function bindSettingsDrag(root){const handle=$('.dismiss-handle',root),sheet=$('.settings-sheet',root);let start=null;handle.addEventListener('pointerdown',e=>{start=e.clientY;handle.setPointerCapture(e.pointerId);});handle.addEventListener('pointermove',e=>{if(start!==null)sheet.style.transform=`translateY(${Math.min(0,e.clientY-start)}px)`;});handle.addEventListener('pointerup',e=>{if(start!==null&&start-e.clientY>32){render('chat','backward');}else{sheet.animate([{transform:sheet.style.transform||'translateY(0)'},{transform:'translateY(0)'}],{duration:180,easing:'cubic-bezier(.22,1,.36,1)'});sheet.style.transform='';}start=null;});handle.addEventListener('pointercancel',()=>{start=null;sheet.style.transform='';});}
function revokeFile(){selectionId++;if(state.selectedFile?.url)URL.revokeObjectURL(state.selectedFile.url);state.selectedFile=null;state.fileReading=false;state.fileError='';}
function sampleCredential(){revokeFile();state.selectedFile={name:'chamber1-演示凭证.png',url:URL.createObjectURL(new Blob([credentialImage()],{type:'image/svg+xml'})),size:'900 × 1200'};if(!['restore','credential-verify'].includes(state.screen))render(category(state.screen)==='restore'?'restore':'credential-verify');else render(state.screen,'forward',{instant:true});}
function chooseFile(file){if(!file)return;revokeFile();const attempt=selectionId,screen=state.screen;if(file.type!=='image/png'||file.size>12*1024*1024){state.fileError='请选择不超过 12 MB 的 PNG 凭证原图。';render(screen,'forward',{instant:true});return;}state.fileReading=true;render(screen,'forward',{instant:true});const reader=new FileReader();reader.onload=()=>{if(attempt!==selectionId||state.screen!==screen)return;state.selectedFile={name:file.name,url:URL.createObjectURL(new Blob([reader.result],{type:file.type})),size:`${Math.max(1,Math.round(file.size/1024))} KB`};state.fileReading=false;render(screen,'forward',{instant:true});};reader.onerror=()=>{if(attempt!==selectionId)return;state.fileReading=false;state.fileError='图片读取失败，请重新选择。';render(screen,'forward',{instant:true});};reader.readAsArrayBuffer(file);}
async function exportSample(next=true){const attempt=transientId,svg=new Blob([credentialImage()],{type:'image/svg+xml'}),url=URL.createObjectURL(svg),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const canvas=document.createElement('canvas');canvas.width=900;canvas.height=1200;canvas.getContext('2d').drawImage(image,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('示例图片生成失败');if(attempt!==transientId)return;const link=document.createElement('a'),downloadUrl=URL.createObjectURL(blob);link.href=downloadUrl;link.download='chamber1-演示凭证.png';link.click();setTimeout(()=>URL.revokeObjectURL(downloadUrl),1000);state.credentialExported=true;if(next){revokeFile();render('credential-verify');}else toast('示例凭证已导出');}catch{toast('示例凭证未能导出，请重试',true);}finally{URL.revokeObjectURL(url);}}
function paintCreation(elapsed){const scene=$('.portal-scene',app);if(!scene)return;const failed=creation.scenario==='failed'&&elapsed>=2100;const hold=creation.scenario==='slow'&&elapsed>=2300;let open=Math.min(1,Math.max(0,(elapsed-3600)/960));open=1-(1-open)**3;const approach=Math.min(1,Math.max(0,(elapsed-4140)/600));scene.style.setProperty('--open',motionReduced()?0:open);scene.style.setProperty('--approach',motionReduced()?0:approach);scene.classList.toggle('is-failed',failed);const title=$('[data-portal-title]',scene),note=$('[data-portal-note]',scene);title.textContent=failed?'门还没有打开':elapsed>=3600?'只属于你们的密室':elapsed>=2400?'让秘密，有处安放':elapsed>=1200?'留住这一刻的私密':'一扇门，只为你们打开';note.textContent=failed?'网络暂时无法连接，准备未完成。':hold?'正在等待连接，密室准备好后继续':elapsed>=3600?'请进':elapsed>=2400?'正在确认密室已就绪':elapsed>=1200?'正在建立加密保护':'正在准备你的密室';$$('.portal-stage-dots span',scene).forEach((el,i)=>{el.classList.toggle('is-active',i===Math.min(2,Math.floor(elapsed/1200)));el.classList.toggle('is-done',elapsed>=(i+1)*1200);});$('.portal-actions',scene).hidden=!failed;const slider=$('#door-seek');if(slider)slider.value=elapsed;const label=$('#seek-label');if(label)label.textContent=`${(elapsed/1000).toFixed(1)}s / 4.9s`;}
function playCreation(scenario=creation.scenario,from=0){cancelAnimationFrame(creationFrame);creation={scenario,running:true,elapsed:from,start:performance.now()-from,paused:false,pauseAt:0};state.fresh=true;render('creation','forward',{instant:true});const frame=now=>{if(state.screen!=='creation'||!creation.running)return;const t=now-creation.start;creation.elapsed=creation.scenario==='slow'?Math.min(t,2300):creation.scenario==='failed'?Math.min(t,2100):t;paintCreation(creation.elapsed);if(creation.scenario==='failed'&&t>=2100){creation.running=false;return;}if(t>=4900&&creation.scenario==='normal'){creation.running=false;render('chat','forward',{instant:true});device.dataset.chromeClosing='creation';const shade=document.createElement('div');shade.className='passage-shade';app.append(shade);shade.animate([{opacity:1},{opacity:0}],{duration:motionReduced()?180:340,fill:'forwards'}).finished.then(()=>{shade.remove();if(device.dataset.chromeClosing==='creation')delete device.dataset.chromeClosing;});return;}creationFrame=requestAnimationFrame(frame);};creationFrame=requestAnimationFrame(frame);}
