let holdTimer;
app.addEventListener('pointerdown',event=>{const hold=event.target.closest('[data-action=hold-cover]');if(!hold||state.screen!=='cover-practice')return;event.preventDefault();hold.classList.add('is-holding');hold.setPointerCapture(event.pointerId);holdTimer=setTimeout(()=>{hold.classList.remove('is-holding');render('cover-settings','backward');toast('演练完成，正式产品会进入身份验证');},1000);});
