document.addEventListener('click',event=>{
  const nav=event.target.closest('#review-nav [data-screen]');if(nav){render(nav.dataset.screen);return;}
  const target=event.target.closest('[data-review-action]');if(!target)return;const action=target.dataset.reviewAction;
  if(action==='play-door'||action==='normal-door'){playCreation('normal');return;}
  if(action==='pause-door'){pauseCreation();return;}
  if(action==='freeze-door'){cancelAnimationFrame(creationFrame);creation.running=false;creation.paused=true;creation.scenario='normal';creation.elapsed=3800;render('creation','forward',{instant:true});return;}
  if(action==='slow-door'){playCreation('slow');return;}
  if(action==='ready-door'){playCreation('normal',2400);return;}
  if(action==='failed-door'){playCreation('failed');return;}
  if(action==='fresh-chat'){state.fresh=true;render('chat','forward',{instant:true});return;}
  if(action==='existing-chat'){state.fresh=false;render('chat','forward',{instant:true});return;}
  if(action==='swap-presence'){state.presence=state.presence==='heart'?'capsule':'heart';render('chat','forward',{instant:true});return;}
  if(action==='show-tip'){state.tip=true;render('chat','forward',{instant:true});return;}
  if(action==='fill-password'){$$('input[type=password],input[type=text]',$('.surface:not(.retiring)',app)).forEach(input=>{input.value=demoPassword;input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));});return;}
  if(action==='wrong-password'){$$('input[name=password]',app).forEach(input=>{input.value='wrong-demo-password';});return;}
  if(action==='sample-credential'){sampleCredential();return;}
  if(action==='credential-reset'){state.credentialSet=false;state.credentialVerified=false;state.credentialExported=false;state.credentialEditing=false;demoPassword='chamber-demo-2026';revokeFile();render('credential');return;}
  if(action==='credential-complete'){state.credentialSet=true;state.credentialVerified=true;state.credentialExported=true;render('credential');return;}
  if(action==='pending-device'){state.pending=true;state.members=Math.min(2,state.members);render('devices');return;}
  if(action==='device-limit'){state.members=3;state.pending=false;render('devices');return;}
  if(action==='reset-devices'){state.members=2;state.pending=false;render('devices');return;}
  if(action==='device-load-failure'){render('devices','forward',{instant:true});const body=$('.page-body',app);body.innerHTML='<div class="restore-symbol">'+icon('info')+'</div><h2 class="restore-headline">暂时无法读取设备</h2><p class="lead" style="text-align:center">请检查网络后重新尝试。</p><button class="btn secondary" style="width:100%;margin-top:24px" type="button" data-go="devices">重新读取</button>';return;}
  if(action==='peer-connected'){state.peerLinked=true;render('peer-link');return;}
  if(action==='peer-failure'){toast('链接未能生成，请检查网络后重试',true);return;}
  if(action==='empty-gallery'||action==='filled-gallery'){state.galleryPopulated=action==='filled-gallery';render('gallery','forward',{instant:true});return;}
  if(action==='save-failure'){state.failSave=!state.failSave;drawInspector();return;}
  if(action==='restore-failure'){state.forceRestoreFailure=!state.forceRestoreFailure;drawInspector();return;}
  if(action==='practice-cover'){render('cover-practice');return;}
  if(action==='complete-hold'){render('cover-settings','backward');toast('演练完成，正式产品会进入身份验证');return;}
  if(action==='go-chat'){render('chat','backward');return;}
});
document.addEventListener('input',event=>{if(event.target.id==='door-seek'){cancelAnimationFrame(creationFrame);creation.running=false;creation.paused=true;creation.elapsed=Number(event.target.value);if(state.screen!=='creation')render('creation','forward',{instant:true,keepInspector:true});paintCreation(creation.elapsed);}});
$('#toggle-theme').addEventListener('click',()=>{document.documentElement.dataset.colorScheme=document.documentElement.dataset.colorScheme==='dark'?'light':'dark';updateChrome();});
$('#palette').addEventListener('change',event=>{document.documentElement.dataset.theme=event.target.value;updateChrome();});
$('#reduced-motion').addEventListener('change',event=>{state.reduced=event.target.checked;app.classList.toggle('is-reduced',motionReduced());if(state.screen==='creation')paintCreation(creation.elapsed);});
$('#large-text').addEventListener('change',event=>{state.large=event.target.checked;app.classList.toggle('large-text',state.large);});
$('#viewport').addEventListener('change',fitDevice);window.addEventListener('resize',fitDevice);window.addEventListener('hashchange',()=>{const screen=location.hash.slice(1);if(screen&&screen!==state.screen)render(screen);});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&creation.running)pauseCreation();});
window.addEventListener('pagehide',()=>{cancelAnimationFrame(creationFrame);clearInterval(restoreTimer);clearTimeout(toastTimer);clearTimeout(holdTimer);revokeFile();});
render(location.hash.slice(1)||'creation','forward',{instant:true});
fitDevice();new ResizeObserver(fitDevice).observe($('.device-stage'));
